from __future__ import unicode_literals

from functools import partial
import unittest
from ute_common_util.test.temp import path_to_resource
from ute_common_config_files.scfc.exceptions import NoSuchManagedObject, ExactlyOneManagedObjectExpected, DuplicatedDistNames
from ute_common_config_files.scfc.scfc import Scfc

path_to_resource = partial(path_to_resource, __name__)
DIST_NAME = 'MRBTS-1/BTSSCL-1/LCELL-1'


class TestRaml(unittest.TestCase):

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_managed_object_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        self.assertEqual(managed_object.xml.tag, '{raml21.xsd}managedObject')
        self.assertEqual(managed_object.xml.get('distName'), DIST_NAME)

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_managed_object_not_found(self, scfc_path):
        with self.assertRaises(NoSuchManagedObject):
            Scfc(scfc_path).find_managed_object('INVALID-1/DIST-2/NAME-3')

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_managed_object_class_found(self, scfc_path):
        self.assertEqual(Scfc(scfc_path).find_managed_object('LCELL', 1).dist_name, DIST_NAME)

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_managed_object_not_found(self, scfc_path):
        with self.assertRaises(NoSuchManagedObject):
            Scfc(scfc_path).find_managed_object('INVALID_CLASS', 1)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_find_managed_object_one_of_many_found(self, scfc_path):
        self.assertEqual(Scfc(scfc_path).find_managed_object('LCELL', 3).id, 3)

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_single_managed_object_not_found(self, scfc_path):
        with self.assertRaises(ExactlyOneManagedObjectExpected):
            Scfc(scfc_path).find_single_managed_object('INVALID_CLASS')

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_find_single_managed_object_multiple_found(self, scfc_path):
        with self.assertRaises(ExactlyOneManagedObjectExpected):
            Scfc(scfc_path).find_single_managed_object('LCELL')

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_single_managed_object_one_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_single_managed_object('LCELL')
        self.assertEqual(managed_object.dist_name, DIST_NAME)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_find_managed_objects_3_found(self, scfc_path):
        managed_objects = Scfc(scfc_path).find_managed_objects('LCELL')
        self.assertEqual(len(managed_objects), 3)
        self.assertEqual(managed_objects[0].id, 2)
        self.assertEqual(managed_objects[1].id, 3)
        self.assertEqual(managed_objects[2].id, 1)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_find_managed_objects_none_found(self, scfc_path):
        managed_objects = Scfc(scfc_path).find_managed_objects('INVALID_CLASS')
        self.assertEqual(managed_objects, [])

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_remove_managed_objects(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 3)
        scfc.remove_managed_objects('LCELL')
        self.assertEqual(scfc.count_managed_objects('LCELL'), 0)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_count_managed_objects(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 3)
        self.assertEqual(scfc.count_managed_objects('NON_EXISTING_OBJECT'), 0)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_check_managed_objects_duplications(self, scfc_path):
        scfc = Scfc(scfc_path)
        scfc.check_managed_objects_duplications()

        lcell = scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-1')
        lcell.clone(new_id=1)

        with self.assertRaises(DuplicatedDistNames):
            scfc.check_managed_objects_duplications()

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_has_managed_object(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertTrue(scfc.has_managed_object('LCELL'))
        self.assertTrue(scfc.has_managed_object('LCELL', 2))
        self.assertFalse(scfc.has_managed_object('LCELL', 6))
        self.assertFalse(scfc.has_managed_object('NON_EXISTING_OBJECT'))
        self.assertFalse(scfc.has_managed_object('NON_EXISTING_OBJECT', 2))
